// ─── Quest Pool Builder ────────────────────────────────────────────────────────
// easy → draw only from easy pool
// medium → draw from easy + medium combined
// hard → draw from all three tiers
export function buildQuestPool(outingId, difficultyId) {
  const tiers = SOLO_QUESTS[outingId]
  if (!tiers) return []
  if (difficultyId === 'easy')   return [...tiers.easy]
  if (difficultyId === 'medium') return [...tiers.easy, ...tiers.medium]
  return [...tiers.easy, ...tiers.medium, ...tiers.hard]
}

// Fisher-Yates shuffle
function shuffle(arr) {
  const a = [...arr]
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]]
  }
  return a
}

// Helper: filter a pool against a Set of already-seen IDs, with cycle reset
// when the remaining unseen pool can't satisfy `count`.
function applyExclusion(pool, count, excludeIds) {
  if (!excludeIds || excludeIds.size === 0) return pool
  const unseen = pool.filter(t => !excludeIds.has(t.id))
  return unseen.length >= count ? unseen : pool   // exhausted → full pool
}

// Helper: shared picker body used by every bar role-pool picker (Duo..Deca).
// All 9 of them are structurally identical; this avoids 9 copies of the same code.
function pickFromRolePool(poolMap, outingId, difficultyId, excludeIds = null) {
  const diff = DIFFICULTIES.find(d => d.id === difficultyId)
  const n    = diff?.taskCount || 5
  const full = poolMap[outingId]?.[difficultyId] || []
  const pool = applyExclusion(full, n, excludeIds)
  return shuffle(pool).slice(0, Math.min(n, pool.length))
}

// Pick N unique random quests from the pool for the given difficulty
export function pickQuestSet(outingId, difficultyId, excludeIds = null) {
  const diff = DIFFICULTIES.find(d => d.id === difficultyId)
  const n = diff?.taskCount || 5
  const pool = applyExclusion(buildQuestPool(outingId, difficultyId), n, excludeIds)
  const shuffled = shuffle(pool)
  return shuffled.slice(0, Math.min(n, shuffled.length))
}

// Pick exactly n quests (for squad mode where count depends on group size)
export function pickNQuests(outingId, difficultyId, n, excludeIds = null) {
  const pool = applyExclusion(buildQuestPool(outingId, difficultyId), n, excludeIds)
  const shuffled = shuffle(pool)
  return shuffled.slice(0, Math.min(n, shuffled.length))
}

// Assign players to tasks so everyone appears in ≥ 2 challenges.
// Each task gets exactly 2 players (or all if group < 2).
export function assignPlayersToTasks(players, tasks) {
  if (!players.length) return tasks.map(t => ({ ...t, assignedPlayers: [] }))
  const tally = Object.fromEntries(players.map(p => [p, 0]))

  return tasks.map(task => {
    const need = Math.min(2, players.length)
    // Sort by fewest assignments, break ties randomly
    const sorted = [...players].sort((a, b) => {
      const d = tally[a] - tally[b]
      return d !== 0 ? d : Math.random() - 0.5
    })
    const assigned = sorted.slice(0, need)
    assigned.forEach(p => tally[p]++)
    return { ...task, assignedPlayers: assigned }
  })
}

// How many tasks needed so every player gets ≥ 2 (2 players per task)
// = max(diff.taskCount, playerCount)  since: tasks * 2 slots / 2 slots-per-task = tasks ≥ players
export function squadTaskCount(difficultyId, playerCount) {
  const diff = DIFFICULTIES.find(d => d.id === difficultyId)
  return Math.max(diff?.taskCount || 5, playerCount)
}

