// Used when squad size is exactly 4. Player labels are substituted with actual
// entered names at display time in SquadMode.jsx.

export const SQUAD_QUAD_QUESTS = {
  bar: {
    easy: [
      // Social
      { id:'b_qe01', title:'The Quad Intro',              desc:'Player 1 approaches a stranger and opens the conversation. Player 2 joins and adds energy. Player 3 joins and makes the stranger laugh. Player 4 arrives last and closes with something that makes the stranger want to keep talking to the group.',                                                                            xp:45 },
      { id:'b_qe02', title:'The Four Way Hype',           desc:'Player 1 introduces Player 2 to a stranger as the most talented person in the room. Player 2 introduces Player 3 to a different stranger as the most interesting person they know. Player 3 introduces Player 4 to a third stranger as someone who is quietly legendary. Player 4 introduces Player 1 to a fourth stranger as the glue that holds the whole group together.',  xp:45 },
      { id:'b_qe03', title:'The Compliment Quad',         desc:'All four players approach the same stranger. Each delivers one compliment about the stranger that builds on the previous one without repeating anything and without any preparation.',                                                                                                                                       xp:40 },
      { id:'b_qe04', title:'The Relay Conversation',      desc:'Player 1 starts a conversation with a stranger and keeps it going for 60 seconds. Player 2 taps in for 60 seconds. Player 3 taps in for 60 seconds. Player 4 closes the conversation on the highest possible note. No stranger should feel the handoff.',                                                                   xp:50 },
      { id:'b_qe05', title:'Four Point Surround',         desc:'Player 1 stands to the left of a stranger at the bar. Player 2 stands to the right. Player 3 stands in front. Player 4 stands just behind the group. All four strike up a coordinated conversation from their positions simultaneously.',                                                                                   xp:45 },
      { id:'b_qe06', title:'The Endorsement Square',      desc:'Player 1 tells a stranger about Player 2\'s best quality. Player 2 tells a different stranger about Player 3\'s best quality. Player 3 tells a different stranger about Player 4\'s best quality. Player 4 tells a different stranger about Player 1\'s best quality. All four must be genuine.',                            xp:50 },
      { id:'b_qe07', title:'The Four Ambassadors',        desc:'All four players split up and spend 15 minutes separately building the reputations of the other three with different strangers. Reconvene and see which player had the most strangers already asking about them.',                                                                                                             xp:45 },
      { id:'b_qe08', title:'Name Network',                desc:'Player 1 learns a stranger\'s name. Player 2 learns their hometown. Player 3 learns their job. Player 4 learns why they\'re out tonight. Combine into one complete profile without the stranger realizing all four were coordinating.',                                                                                       xp:40 },
      { id:'b_qe09', title:'The Buildup Quartet',         desc:'Player 1 starts a story about something that happened tonight. Player 2 adds a detail. Player 3 adds a bigger detail. Player 4 delivers the punchline. Tell it to a stranger who must find it genuinely funny or interesting.',                                                                                               xp:50 },
      { id:'b_qe10', title:'Four Way Handshake',          desc:'All four players invent a group handshake that involves all four people simultaneously and perform it perfectly in front of a stranger on the very first attempt.',                                                                                                                                                             xp:45 },
      // Drinking & Ordering
      { id:'b_qe11', title:'Quad Synchronized Order',     desc:'All four players walk up to the bar and order four completely different drinks at the exact same time without any prior discussion about what each person is getting.',                                                                                                                                                         xp:40 },
      { id:'b_qe12', title:'Round Robin Four',            desc:'Player 1 buys round one. Player 2 buys round two. Player 3 buys round three. Player 4 buys round four. The rotation must be followed strictly all night with no skipping or substituting.',                                                                                                                                   xp:45 },
      { id:'b_qe13', title:'Blind Quad',                  desc:'Player 4 orders drinks for all four players without asking anyone what they want. All four must finish whatever arrives without complaint.',                                                                                                                                                                                   xp:50 },
      { id:'b_qe14', title:'Budget Squad',                desc:'Player 1 sets a $30 budget. Player 2 places the order. Player 3 negotiates if needed. Player 4 pays and confirms it comes in under budget including tip.',                                                                                                                                                                    xp:45 },
      { id:'b_qe15', title:'Drink Swap Square',           desc:'Player 1 passes their drink to Player 2. Player 2 passes to Player 3. Player 3 passes to Player 4. Player 4 passes to Player 1. All four finish the drink they end up with.',                                                                                                                                                xp:50 },
      { id:'b_qe16', title:'Shot Solidarity Four',        desc:'Player 1 picks the shot. Player 2 orders it. Player 3 pays for it. Player 4 lines them up. All four take it simultaneously without knowing what it is until it arrives.',                                                                                                                                                     xp:40 },
      { id:'b_qe17', title:'Relay Order Quartet',         desc:'Player 1 tells the bartender the glass. Player 2 tells them the base spirit. Player 3 tells them the mixer. Player 4 tells them one garnish. Accept whatever the bartender assembles from those four inputs.',                                                                                                                xp:45 },
      { id:'b_qe18', title:'Tasting Panel Four',          desc:'Each player orders a completely different drink. All four taste every drink and each gives exactly one sentence of review for each. Sixteen reviews total delivered to the bartender.',                                                                                                                                        xp:50 },
      { id:'b_qe19', title:'Price Guessers Four',         desc:'Before the round arrives all four players guess the total cost. The two players furthest off split the cost of the next round between them.',                                                                                                                                                                                  xp:45 },
      { id:'b_qe20', title:'The Quad Tab',                desc:'Player 1 opens the tab. Player 2 manages the running total. Player 3 monitors and reports when the budget is getting close. Player 4 closes the tab at the end. No player can do another\'s job.',                                                                                                                          xp:40 },
      // Bar Exploration
      { id:'b_qe21', title:'Four Way Scout',              desc:'Player 1 scouts the bar area. Player 2 scouts the seating area. Player 3 scouts the outdoor area. Player 4 scouts the back or lounge area. All four report back simultaneously and the group votes on the best spot.',                                                                                                        xp:40 },
      { id:'b_qe22', title:'Specials Sweep Four',         desc:'Player 1 finds drink specials. Player 2 finds food specials. Player 3 finds any events or promotions. Player 4 finds the best value item on the entire menu. All four present findings as a coordinated briefing.',                                                                                                           xp:45 },
      { id:'b_qe23', title:'Staff Network Four',          desc:'Player 1 learns the bartender\'s name. Player 2 learns a server\'s name. Player 3 learns the door staff\'s name. Player 4 learns the name of any fourth staff member. All four names must be confirmed before the mission is complete.',                                                                                     xp:50 },
      { id:'b_qe24', title:'Venue Graders Four',          desc:'Player 1 grades the music. Player 2 grades the atmosphere. Player 3 grades the service. Player 4 grades the value for money. Combine all four into one official squad verdict and present it to the bartender.',                                                                                                              xp:45 },
      { id:'b_qe25', title:'Speed Mappers Four',          desc:'Divide the bar into four sections. Each player maps their section from memory. Combine all four into one complete venue map on a napkin within 8 minutes of arriving.',                                                                                                                                                        xp:40 },
      { id:'b_qe26', title:'Bathroom Correspondents Four',desc:'Player 4 checks both bathrooms and reports to Player 3. Player 3 relays to Player 2. Player 2 relays to Player 1. Player 1 must report the full situation to a stranger with full accuracy.',                                                                                                                                xp:40 },
      { id:'b_qe27', title:'The Four Man Advance',        desc:'Player 1 goes ahead to the next venue and secures a spot. Player 2 manages getting the group out of the current bar. Player 3 handles transport. Player 4 does a final headcount before anyone moves.',                                                                                                                       xp:50 },
      { id:'b_qe28', title:'Vibe Timeline Four',          desc:'Player 1 tracks music every 20 minutes. Player 2 tracks crowd energy every 20 minutes. Player 3 tracks service speed every 20 minutes. Player 4 tracks overall vibe every 20 minutes. Compare all four timelines at the end of the night.',                                                                                  xp:45 },
      { id:'b_qe29', title:'Bar Fact Collectors Four',    desc:'Player 1 gets a fact from a bartender. Player 2 gets a fact from a server. Player 3 gets a fact from a regular. Player 4 gets a fact from a stranger visiting for the first time. Compare all four and find the most interesting one.',                                                                                       xp:45 },
      { id:'b_qe30', title:'Photo Assignment Four',       desc:'Player 1 handles group photos. Player 2 handles candid shots. Player 3 handles venue and atmosphere. Player 4 handles video clips. Combine everything at the end into one complete story of the night.',                                                                                                                      xp:40 },
      // Games & Challenges
      { id:'b_qe31', title:'Four Way RPS',                desc:'All four play rock paper scissors simultaneously. Last place each round must talk to a stranger for 90 seconds. Play five rounds.',                                                                                                                                                                                           xp:45 },
      { id:'b_qe32', title:'Prediction Four',             desc:'Each player predicts the next song. Whoever is furthest off buys the next round. Play this every 30 minutes all night.',                                                                                                                                                                                                      xp:50 },
      { id:'b_qe33', title:'Word Ban Four',               desc:'Player 1 bans a word for Player 2. Player 2 bans one for Player 3. Player 3 bans one for Player 4. Player 4 bans one for Player 1. First to say their banned word buys a round for the person who banned it.',                                                                                                               xp:40 },
      { id:'b_qe34', title:'Hot Take Bracket',            desc:'All four share an unpopular opinion with a stranger. The stranger ranks them from mildest to wildest. Bottom two in each round debate to stay in. Last standing wins.',                                                                                                                                                        xp:45 },
      { id:'b_qe35', title:'Coin Court Four',             desc:'Player 1 and Player 2 debate a topic. Player 3 and Player 4 are the judges. Roles rotate every debate. Losers buy a drink for the winning side.',                                                                                                                                                                             xp:50 },
      { id:'b_qe36', title:'Napkin Pictionary Four',      desc:'Player 1 draws. Player 2 guesses. Player 3 gives one hint after 15 seconds. Player 4 gives a second hint after 30 seconds. Rotate until everyone has drawn twice.',                                                                                                                                                           xp:45 },
      { id:'b_qe37', title:'Speed Debate Four',           desc:'Player 1 and Player 2 argue one side. Player 3 and Player 4 argue the other side. A stranger judges three rounds. Losing team buys the next round.',                                                                                                                                                                          xp:50 },
      { id:'b_qe38', title:'Best Story Four',             desc:'All four tell their best story from the last month to a stranger. The stranger picks the winner. The other three buy the winner\'s next drink.',                                                                                                                                                                               xp:40 },
      { id:'b_qe39', title:'Stranger Opinion Four',       desc:'All four ask the same question to four different strangers. Reconvene and rank the answers from most common to most surprising.',                                                                                                                                                                                              xp:45 },
      { id:'b_qe40', title:'The Tiebreaker Panel',        desc:'Player 1 and Player 2 get into a disagreement. Player 3 and Player 4 are the panel. Both panelists must agree on the ruling or they must find a fifth stranger to break the tie.',                                                                                                                                            xp:50 },
      // Fun & Silly
      { id:'b_qe41', title:'Alter Ego Four',              desc:'All four adopt completely different personas for 20 minutes. New name, new job, new personality. No two personas can share any characteristics.',                                                                                                                                                                              xp:50 },
      { id:'b_qe42', title:'Four Man Entrance',           desc:'All four plan a coordinated dramatic entrance into a new section of the bar or a new venue. Player 1 leads. Player 2 and Player 3 flank. Player 4 closes. Get a visible reaction from at least 4 people.',                                                                                                                   xp:45 },
      { id:'b_qe43', title:'Tourist Squad',               desc:'All four pretend to be tourists in this city for the first time. Player 1 handles asking for directions. Player 2 handles mispronouncing everything. Player 3 handles taking photos of mundane things like they\'re landmarks. Player 4 handles expressing awe at everything.',                                               xp:50 },
      { id:'b_qe44', title:'Silence Game Four',           desc:'All four bet on who can stay silent longest in a social setting. Player 4 is eliminated first every time and must buy a drink. Last person silent wins the round.',                                                                                                                                                            xp:45 },
      { id:'b_qe45', title:'Impression Tournament',       desc:'Player 1 impersonates Player 2. Player 2 impersonates Player 3. Player 3 impersonates Player 4. Player 4 impersonates Player 1. A stranger ranks all four from most to least accurate.',                                                                                                                                     xp:40 },
      { id:'b_qe46', title:'The Prop Show Four',          desc:'Each player picks one item from the bar. All four must use their item in a 90-second coordinated performance that tells a complete story with no prior rehearsal.',                                                                                                                                                             xp:45 },
      { id:'b_qe47', title:'Compliment Merchants Four',   desc:'Divide the bar into four zones. Each player owns their zone for 10 minutes and gives genuine compliments to everyone in it. Count at the end to see who reached the most people.',                                                                                                                                             xp:40 },
      { id:'b_qe48', title:'Fashion Week Four',           desc:'Player 2, Player 3, and Player 4 commentate as Player 1 walks through the bar like a runway. Player 1 fully commits. Rotate until all four have done a runway walk with three commentators.',                                                                                                                                 xp:50 },
      { id:'b_qe49', title:'The Long Game Four',          desc:'Each player picks one stranger at the very start of the night. By the end all four must know their stranger\'s name, job, hometown, and one fun fact without ever directly asking any of those questions.',                                                                                                                   xp:45 },
      { id:'b_qe50', title:'Squad Critique Four',         desc:'All four give each other one piece of honest feedback about how they\'re performing socially tonight. Every player must give three reviews and receive three. No sugarcoating allowed.',                                                                                                                                      xp:40 },
    ],
    medium: [
      // Social
      { id:'b_qm01', title:'The Four Act Story',          desc:'Player 1 sets the scene to a stranger. Player 2 introduces the conflict. Player 3 escalates it. Player 4 delivers the resolution and punchline. The stranger must be visibly engaged through all four acts without any of the players prompting them to stay.',                                                               xp:85 },
      { id:'b_qm02', title:'The Four Archetypes',         desc:'Player 1 plays the enthusiastic one. Player 2 plays the skeptical one. Player 3 plays the mysterious one. Player 4 plays the unpredictable wildcard. Together approach a group of strangers and collectively convince them to try something new using the dynamic.',                                                          xp:80 },
      { id:'b_qm03', title:'The Four Ambassadors Advanced',desc:'All four players separate and spend 25 minutes building the reputations of the other three with different strangers across the whole bar. When all four reunite the player who had the most strangers already asking about them wins and picks the next bar.',                                                                 xp:85 },
      { id:'b_qm04', title:'Stranger Adoption Four',      desc:'Player 1 finds a solo stranger and brings them to Player 2. Player 2 introduces them to Player 3. Player 3 introduces them to Player 4. Player 4 integrates them completely into the group for the rest of the night ensuring they feel like a fifth original member.',                                                      xp:80 },
      { id:'b_qm05', title:'The Rotating Spokesperson',   desc:'All four approach a group of strangers. Every 45 seconds the lead spokesperson rotates to the next player with no signal or discussion. The conversation must never drop in energy at any transition point.',                                                                                                                  xp:85 },
      { id:'b_qm06', title:'Quad Merger',                 desc:'Player 1 befriends a group of strangers. Player 2 befriends a completely different group. Player 3 befriends a third group. Player 4 acts as the connector who introduces all three groups to each other within 30 minutes of the mission starting.',                                                                         xp:80 },
      { id:'b_qm07', title:'The Credibility Quad',        desc:'Player 1 establishes trust with a stranger through one good recommendation. Player 2 uses that trust to get a bigger commitment from the stranger. Player 3 uses the accumulated trust for an even bigger ask. Player 4 closes by getting the stranger to introduce all four players to someone else.',                      xp:75 },
      { id:'b_qm08', title:'The Four Translators',        desc:'Player 2 speaks only in gibberish. Player 1 translates everything into English for a stranger. Player 3 translates everything the stranger says back into a different made-up language for Player 4. Player 4 translates that into a third made-up language for Player 2. Maintain for 4 full minutes without breaking.',   xp:85 },
      { id:'b_qm09', title:'Stranger Squad Builder Four', desc:'Each player separately recruits one willing stranger into a temporary expanded squad. All four strangers plus the original four must be hanging out together within 30 minutes. No stranger can know they were recruited as part of a mission.',                                                                               xp:80 },
      { id:'b_qm10', title:'The Four Layer Reveal',       desc:'Player 1 tells a stranger one interesting thing about Player 4 and asks them not to mention it. Player 2 tells the same stranger a second thing. Player 3 tells them a third thing. Player 4 then meets the stranger for the first time and the stranger must naturally bring up all three things within the conversation.',  xp:75 },
      // Drinking & Ordering
      { id:'b_qm11', title:'Bartender Build Four',        desc:'Player 1 tells the bartender the group\'s mood. Player 2 tells them the budget per drink. Player 3 tells them one required ingredient. Player 4 tells them one ingredient to avoid. Accept whatever the bartender makes for all four with absolutely no further input.',                                                      xp:85 },
      { id:'b_qm12', title:'Progressive Escalation Four', desc:'Player 1 orders the cheapest drink on the menu. Player 2 orders the second cheapest. Player 3 orders a mid-range drink. Player 4 orders the most expensive. Next round all four move up one tier. Continue until someone hits their personal limit.',                                                                         xp:80 },
      { id:'b_qm13', title:'The Cocktail Committee Four', desc:'Player 1 proposes a drink concept to the bartender. Player 2 negotiates the ingredients. Player 3 names it. Player 4 negotiates the price. All four must drink it and each deliver a one-sentence tasting note to the bartender.',                                                                                           xp:85 },
      { id:'b_qm14', title:'Blind Square',                desc:'Player 1 orders for Player 2. Player 2 orders for Player 3. Player 3 orders for Player 4. Player 4 orders for Player 1. All four must finish what they received and rate the person who ordered for them out of 10.',                                                                                                        xp:80 },
      { id:'b_qm15', title:'Budget Masters Four',         desc:'Player 1 sets the total budget. Player 2 places all orders. Player 3 manages the running total and gives warnings. Player 4 is the independent auditor who verifies every number at the end. Land within $5 of the budget.',                                                                                                 xp:75 },
      { id:'b_qm16', title:'The Flavor Brief Four',       desc:'Player 1 describes their drink using only colors. Player 2 using only emotions. Player 3 using only textures. Player 4 using only sounds. The bartender makes one drink per description and all four must finish theirs.',                                                                                                    xp:85 },
      { id:'b_qm17', title:'Round Consequence Four',      desc:'Before every round all four players guess the total cost. The player furthest off every round must add a drink to the next order for a stranger at the bar.',                                                                                                                                                                  xp:80 },
      { id:'b_qm18', title:'The Drink Curriculum Four',   desc:'Player 1 orders something classic. Player 2 orders something modern. Player 3 orders something local. Player 4 orders something the bartender invented themselves. All four taste each other\'s and the bartender gives a 2-minute education on all four.',                                                                  xp:75 },
      { id:'b_qm19', title:'Last Call Logistics Four',    desc:'Player 1 monitors time all night and gives 30, 15, and 5-minute warnings. Player 2 tracks everyone\'s drink levels. Player 3 decides the final order for the group. Player 4 executes at the bar and makes sure everyone has something in hand at closing.',                                                                 xp:85 },
      { id:'b_qm20', title:'The Quad Tab Mastery',        desc:'Player 1 owns the first quarter of the night\'s spending. Player 2 owns the second quarter. Player 3 owns the third quarter. Player 4 owns the final quarter and closes the tab. Each handoff must be seamless and the total must land within $10 of a budget agreed at the very start of the night.',                      xp:80 },
      // Bar Exploration & Venue
      { id:'b_qm21', title:'The Four Reporters',          desc:'Player 1 interviews staff about the bar\'s best offerings. Player 2 interviews regulars about what makes it special. Player 3 interviews first-timers about their impressions. Player 4 observes the physical space and documents atmosphere details. All four combine into one comprehensive bar profile delivered to the manager.',  xp:85 },
      { id:'b_qm22', title:'Undercover Inspectors Four',  desc:'All four spend one hour as mystery shoppers. Player 1 evaluates drinks. Player 2 evaluates service. Player 3 evaluates atmosphere. Player 4 evaluates value for money. Deliver one combined written report on a napkin to the manager at the end of the hour.',                                                               xp:80 },
      { id:'b_qm23', title:'The Four Locals Network',     desc:'Player 1 finds the most knowledgeable local and extracts their best neighborhood tips. Player 2 finds a regular for bar insider knowledge. Player 3 finds a staff member for an insider recommendation. Player 4 finds a visitor from out of town for an outsider perspective. All four reports are combined and actioned before the night ends.',  xp:85 },
      { id:'b_qm24', title:'Staff Relationship Four',     desc:'Each player builds a genuine relationship with a different staff member. By the end of the night all four staff members must know all four players by name and at least one of them must come find the squad to say goodbye before they leave.',                                                                               xp:75 },
      { id:'b_qm25', title:'Night Documentarians Four',   desc:'Player 1 handles photography. Player 2 handles video. Player 3 handles written notes and memorable quotes. Player 4 handles audio recordings of ambient sounds and conversations with permission. All four combine at the end into a complete multi-format documentary of the night.',                                         xp:80 },
      { id:'b_qm26', title:'Bar Crawl Command Four',      desc:'Player 1 is the navigator planning each venue and route. Player 2 is the social director handling first impressions at each bar. Player 3 is the logistics manager handling transport and timing. Player 4 is the experience director deciding what the group does at each venue. Execute a 3-bar crawl with every player fulfilling their role perfectly.',  xp:85 },
      { id:'b_qm27', title:'Atmosphere Analysts Four',    desc:'Player 1 documents music in 15-minute intervals. Player 2 documents crowd density. Player 3 documents service speed. Player 4 documents overall energy. Overlay all four charts at the end and present a complete picture of how the night evolved to the bartender.',                                                         xp:80 },
      { id:'b_qm28', title:'Venue Biography Four',        desc:'Player 1 researches the bar\'s founding story. Player 2 researches the neighborhood history. Player 3 researches notable events or famous patrons. Player 4 researches how the bar has changed over time. Combine into a complete biography recited to a stranger who finds it genuinely interesting.',                        xp:75 },
      { id:'b_qm29', title:'The Full Insiders Four',      desc:'Each player independently uncovers a different piece of non-public information about the bar — a secret menu item, an upcoming event, a staff tradition, a piece of history. All four must be different and verified by a staff member before the mission is complete.',                                                       xp:85 },
      { id:'b_qm30', title:'Split Recon Full Report Four',desc:'Player 1 evaluates the bar as a first date venue. Player 2 as a birthday celebration venue. Player 3 as a business meeting venue. Player 4 as an after-work drinks venue. All four present their assessments and collectively vote on which occasion the bar is actually best suited for.',                                  xp:80 },
      // Games & Challenges
      { id:'b_qm31', title:'The Long Con Four',           desc:'All four agree on a completely fictional shared backstory at the start of the night. Tell the same story consistently to at least 8 different strangers across the night. Zero contradictions allowed across all four players at any point.',                                                                                  xp:85 },
      { id:'b_qm32', title:'Four Way Debate Tournament',  desc:'All four each argue a different position on a ridiculous topic. Find a stranger to judge four full rounds. Loser of each round buys a drink. Overall loser buys the final round for everyone.',                                                                                                                               xp:80 },
      { id:'b_qm33', title:'Prediction Masters Four',     desc:'At the start of the night each player makes 10 predictions. At the end the player who got the most right has their tab paid by the other three combined.',                                                                                                                                                                    xp:85 },
      { id:'b_qm34', title:'Trust Rotation Four',         desc:'Player 1 makes every decision for all four for the first 45 minutes. Player 2 takes control for the next 45. Player 3 takes control for the next 45. Player 4 controls the final hour. Zero complaints or overrides permitted from anyone during another player\'s turn.',                                                    xp:80 },
      { id:'b_qm35', title:'The Four Witnesses',          desc:'Each player independently writes down the 5 most interesting things they witnessed all night without discussing it with the others. Any item appearing on three or more lists scores triple. Highest combined score wins.',                                                                                                     xp:75 },
      { id:'b_qm36', title:'Alias Operation Four',        desc:'All four take fake names, jobs, and hometowns that are completely different and internally consistent as a group. Get at least 12 strangers to know your fake identities. First player to break character buys the next round for all three others.',                                                                          xp:85 },
      { id:'b_qm37', title:'Story Chain Four',            desc:'Player 1 starts a story to a stranger. Player 2 continues after exactly 30 seconds with no signal. Player 3 continues after another 30 seconds. Player 4 delivers the ending after a final 30 seconds. The stranger must be genuinely invested throughout.',                                                                 xp:80 },
      { id:'b_qm38', title:'The Four Arbiters',           desc:'All four position themselves as the unofficial judges of the bar all night. Get at least 8 different strangers to come to them to settle a debate or get an opinion or recommendation.',                                                                                                                                      xp:75 },
      { id:'b_qm39', title:'Night Detectives Four',       desc:'All four pick the same target stranger at the start of the night without the stranger knowing. Each player independently gathers as many facts as possible through observation and indirect conversation only. Compare findings at the end and build the most complete profile possible.',                                      xp:85 },
      { id:'b_qm40', title:'The Stakes Four',             desc:'All four agree on one high stakes personal consequence at the start of the night. Compete on an agreed metric all night. A panel of two neutral strangers determines the winner and the three losers must fulfill the consequence immediately.',                                                                               xp:80 },
      // Fun & Silly
      { id:'b_qm41', title:'The Four Act Film',           desc:'Player 1 directs. Player 2 is the lead actor. Player 3 is the narrator providing live voiceover from the audience. Player 4 handles music by humming a live soundtrack throughout. Produce a 2-minute film with at least 3 stranger cameos.',                                                                                xp:85 },
      { id:'b_qm42', title:'Method Partnership Four',     desc:'All four commit to a fictional group dynamic for the entire night that none of them break under any circumstances. Options include a world-famous heist crew, a royal family on an incognito night out, four rival spies at the same bar, or any dynamic all four agree on before entering.',                                 xp:80 },
      { id:'b_qm43', title:'Live Podcast Four',           desc:'Player 1 hosts. Player 2 co-hosts. Player 3 is the roving field correspondent. Player 4 is the producer who decides topics, manages time, and signals transitions. Record a genuine 12-minute episode with at least 4 stranger interviews.',                                                                                 xp:85 },
      { id:'b_qm44', title:'The Grand Entrance Four',     desc:'All four plan a dramatic entrance into a new bar on the crawl. Player 1 enters and creates a distraction. Player 2 enters and escalates. Player 3 enters and redirects attention. Player 4 enters last and lands the moment. Get a visible reaction from at least 6 people.',                                                xp:75 },
      { id:'b_qm45', title:'Four Man Roast',              desc:'Player 1 roasts Player 2 for 90 seconds to willing strangers. Player 2 roasts Player 3. Player 3 roasts Player 4. Player 4 roasts Player 1. Strangers score each roast out of 10. Bottom two scores split the cost of the winner\'s next round.',                                                                           xp:85 },
      { id:'b_qm46', title:'The Four Man Heist',          desc:'All four plan and execute a completely harmless multi-step mission requiring all four to play specific simultaneous roles. The objective must be agreed before entering and completed within 60 minutes using only charm, coordination, and timing.',                                                                           xp:80 },
      { id:'b_qm47', title:'Undercover Celebrities Four', desc:'Player 1 is a globally famous artist performing under a pseudonym. Player 2 is their manager. Player 3 is their head of security. Player 4 is an overexcited fan who keeps breaking through. Maintain the dynamic all night and measure how many strangers engage with it.',                                                  xp:75 },
      { id:'b_qm48', title:'The Farewell Tour Four',      desc:'All four tell every stranger they meet that tonight is their final night together as a group before the squad permanently splits up. Make every interaction feel genuinely momentous. Get at least 12 strangers to offer heartfelt goodbyes before you leave.',                                                                xp:85 },
      { id:'b_qm49', title:'The Slow Build Bit Four',     desc:'Player 1 plants a callback at the very start of the night with 6 different strangers. Player 2 references it mid-night. Player 3 references it again later. Player 4 pays it off in one final moment at the end in front of as many of those original strangers as possible.',                                              xp:80 },
      { id:'b_qm50', title:'Squad Legacy Four',           desc:'All four leave something behind at the bar that staff will genuinely remember. All four items must connect and tell one complete story when placed together. Get a staff member to acknowledge all four items and understand the complete story before you leave.',                                                              xp:75 },
    ],
    hard: [
      // Social
      { id:'b_qh01', title:'The Full Quad Merge',         desc:'Player 1 befriends a group of strangers. Player 2 befriends a completely different group. Player 3 befriends a third group. Player 4 acts as the master connector engineering a meeting between all three stranger groups and the original four. By the end all groups must be one unified unit with none of the stranger groups aware the merge was orchestrated.',  xp:130 },
      { id:'b_qh02', title:'Reputation by Network Four',  desc:'All four spend the first 30 minutes separately building the other three players\' reputations with different strangers across the bar. By reunion time strangers who haven\'t met the squad should already be asking about specific players by name.',                                                                          xp:125 },
      { id:'b_qh03', title:'The Social Architects Four',  desc:'Each player identifies one stranger who appears to be having a below average night. All four independently and genuinely invest time in making those four strangers\' nights significantly better. All four targets must be visibly having more fun by the end of the mission than when it started.',                           xp:130 },
      { id:'b_qh04', title:'Cold Bar Transformation Four',desc:'All four enter a visibly quiet bar. Player 1 works on staff energy. Player 2 works on the crowd. Player 3 works on the physical atmosphere through music requests and movement. Player 4 works on connecting isolated individuals to each other. Get a staff member to acknowledge the change in the room unprompted.',        xp:125 },
      { id:'b_qh05', title:'The Connector Web Four',      desc:'Player 1 meets stranger A and introduces them to Player 2. Player 2 introduces stranger A to stranger B and Player 3. Player 3 introduces stranger B to stranger C and Player 4. Player 4 introduces stranger C to stranger D. Build a web of at least 10 people who all know each other by the end of the night with all four players as the connectors.',  xp:120 },
      { id:'b_qh06', title:'Squad Ambassadors Four',      desc:'All four separately build enough rapport with four different groups of strangers that each group invites one of the players to join them for the rest of the night. All four must then reconvene and diplomatically bring all four new groups together into one without anyone feeling excluded.',                              xp:130 },
      { id:'b_qh07', title:'The Legend Makers Four',      desc:'Player 1 does something genuinely memorable. Player 2 tells the story to 6 strangers making it more epic each time. Player 3 confirms the story to anyone who asks with additional embellishment. Player 4 creates a physical artifact of the moment (napkin drawing, written account). By the end Player 1 must be approached by someone who heard the story fourth-hand.',  xp:125 },
      { id:'b_qh08', title:'Full Room Coverage Four',     desc:'Divide the bar into four equal sections. Each player takes one section. By the end of the night all four must have had a genuine conversation with every single person in their section and be able to name every person they spoke to.',                                                                                       xp:120 },
      { id:'b_qh09', title:'Four Degrees of Separation',  desc:'Player 1 meets a stranger and finds a genuine connection to Player 2. Player 2 meets a different stranger and finds a genuine connection to Player 3. Player 3 meets a third stranger and finds a genuine connection to Player 4. Player 4 meets a fourth stranger and finds a genuine connection back to Player 1. All connections must be entirely real.',  xp:130 },
      { id:'b_qh10', title:'Social Legends Four',         desc:'By the time all four players leave the bar, get a staff member, a regular, and four different groups of strangers to all voluntarily tell the squad to come back without any of the four players asking hinting or suggesting it.',                                                                                             xp:125 },
      // Drinking & Ordering
      { id:'b_qh11', title:'Bartender\'s Masterclass Four',desc:'Player 1 builds enough rapport with the bartender to get them to teach all four players how to make their signature drink. Player 2 takes detailed notes. Player 3 asks genuine technical questions. Player 4 films the tutorial with permission. All four then attempt to make the drink themselves under the bartender\'s supervision.',  xp:130 },
      { id:'b_qh12', title:'Zero Repeat Square',          desc:'All four players must each order a completely different drink every single round all night with zero repeats across all four players at any point throughout the entire night. Track every single order on a running napkin list.',                                                                                              xp:125 },
      { id:'b_qh13', title:'The Full Menu Four',          desc:'All four players must collectively order every single category on the drink menu between them across the night. At the end all four present a comprehensive and honest rating of every category directly to the head bartender.',                                                                                               xp:120 },
      { id:'b_qh14', title:'Budget Championship Four',    desc:'Player 1 sets a hard total budget for all four for the entire night. Player 2 places all orders and manages spending. Player 3 gives hourly budget updates to the group. Player 4 is the independent auditor who verifies every number and settles disputes. Land within $5 of the budget at the end of the night.',          xp:130 },
      { id:'b_qh15', title:'Comp Champions Four',         desc:'All four must each independently get something complimentary from the bar through genuine charm and relationship building alone. None of the four can tell the others what they\'re pursuing. All four must succeed before the mission is complete.',                                                                           xp:125 },
      { id:'b_qh16', title:'The Invisible Menu Four',     desc:'All four spend the entire night ordering drinks that are not on the menu by describing what they want to the bartender. Every order across all four players must be completely unique throughout the night.',                                                                                                                   xp:120 },
      { id:'b_qh17', title:'Parlay Masters Four',         desc:'Player 1 makes a bet on a prediction. If they win Player 2 parlays into a bigger bet. If Player 2 wins Player 3 parlays into an even bigger bet. If Player 3 wins Player 4 parlays into the final biggest bet of the night. All four must agree on each bet before it is placed.',                                           xp:130 },
      { id:'b_qh18', title:'The Complete Tab Mastery',    desc:'The night is divided into four equal time segments. Each player owns one segment and manages all spending for the whole group during their window. Every handoff must be seamless. The total must land within $5 of a budget agreed before the first drink is ordered.',                                                       xp:125 },
      { id:'b_qh19', title:'Bartender Trust Fund Four',   desc:'All four agree to let the bartender make every single drink decision for the entire group for one full hour. Player 1 communicates the mood. Player 2 communicates the budget. Player 3 communicates any hard limits. Player 4 tips after every round. Accept everything that arrives without complaint or modification.',   xp:120 },
      { id:'b_qh20', title:'Round Robin Consequence Four',desc:'Before every round all four guess the total cost. Whoever is furthest off every round must add an extra drink to the next order for a stranger at the bar. Track and fulfill this all night and count how many strangers benefit from the game by the end.',                                                                   xp:130 },
      // Bar Mastery & Venue
      { id:'b_qh21', title:'Full Staff Relationship Four',desc:'Each player builds a genuine relationship with a different staff member. By the end of the night all four staff members must know all four players by name, have had a real conversation with at least two of the players, and at least two staff members must seek out the squad to say a genuine goodbye before they leave.',  xp:130 },
      { id:'b_qh22', title:'The Bar Historians Four',     desc:'Player 1 researches the bar\'s complete founding story through staff. Player 2 researches the building and neighborhood history through locals. Player 3 researches notable events or famous patrons through regulars. Player 4 researches how the bar has changed over time and where it\'s heading through the manager. Combine into a presentation delivered to a stranger who finds it genuinely fascinating.',  xp:125 },
      { id:'b_qh23', title:'Undercover Owners Four',      desc:'All four spend the night in character as a serious investment group evaluating the bar for acquisition. Player 1 leads operations assessment. Player 2 leads customer experience evaluation. Player 3 leads brand and atmosphere analysis. Player 4 leads financial and value assessment. Compile a genuine written report and deliver it to the manager at the end of the night.',  xp:120 },
      { id:'b_qh24', title:'The Regulars Infiltration Four',desc:'Each player must independently convince a different genuine regular to introduce them to the bartender as if they are a longtime regular who has been coming for years. All four introductions must happen on the same night to four different regulars and four different bartenders or staff members.',                      xp:130 },
      { id:'b_qh25', title:'Venue Transformation Report Four',desc:'Player 1 identifies three things the bar does exceptionally well with specific examples. Player 2 identifies three constructive improvements with detailed suggestions. Player 3 identifies three things no competitor does. Player 4 identifies three trends the bar could capitalize on. Get the manager to engage genuinely with all four presentations in one sitting.',  xp:125 },
      { id:'b_qh26', title:'Bar Crawl Mastery Four',      desc:'Player 1 plans a 5-bar crawl with specific timing and rationale. Player 2 handles all social introductions at each venue. Player 3 handles all transport and logistics. Player 4 handles the experience at each venue including what the group does and how long they stay. Execute the complete crawl with every player fulfilling their role at every single venue.',  xp:120 },
      { id:'b_qh27', title:'The Complete Insiders Four',  desc:'Each player independently uncovers two different pieces of non-public information about the bar. All eight pieces must be entirely different from each other and every single one must be verified by a staff member before the mission is declared complete.',                                                                  xp:130 },
      { id:'b_qh28', title:'Night Shift Chronicles Four', desc:'Each player shadows a different staff member through conversation for 30 minutes learning about their specific experience of the night. All four combine their reports into a complete and coherent picture of what it is genuinely like to work at this bar on this specific night.',                                          xp:125 },
      { id:'b_qh29', title:'Legacy Builders Four',        desc:'All four leave something behind at the bar that staff will genuinely remember long after the night ends. All four items must connect and together tell one complete story. Get the manager specifically to acknowledge all four items, understand the complete story, and express genuine appreciation before you leave.',       xp:120 },
      { id:'b_qh30', title:'The Complete Guide Four',     desc:'All four spend the night gathering enough information to produce a comprehensive guide to the bar and its neighborhood. Player 1 covers drinks and food in detail. Player 2 covers atmosphere, music, and best times to visit. Player 3 covers nearby recommendations. Player 4 covers the bar\'s identity and who it\'s really for. Compile and present the complete guide to a stranger visiting the city for the very first time.',  xp:130 },
      // Games & Challenges
      { id:'b_qh31', title:'The Full Con Four',           desc:'All four invent a detailed shared fictional identity — a touring band, a film production crew, a sports team, a startup — and commit to it completely for the entire night. Get at least 15 different strangers to believe and fully engage with the fiction with zero contradictions across all four players at any point.',  xp:130 },
      { id:'b_qh32', title:'The Prediction Championship Four',desc:'At the start of the night each player makes 15 predictions about the evening. Track every single one meticulously. At the end the player with the most correct predictions has their entire tab paid by the other three.',                                                                                               xp:125 },
      { id:'b_qh33', title:'The Trust Gauntlet Four',     desc:'Each player controls all decisions for the entire group during their 45-minute window. Every decision includes drinks, seating, conversations, movements, and social targets. Absolute zero complaints or overrides from any player during another player\'s window of control.',                                               xp:120 },
      { id:'b_qh34', title:'Quadruple Alias Night',       desc:'All four operate under completely false identities all night. Names, professions, backstories, and hometowns must be entirely consistent across all four personas as a believable group. Get at least 18 strangers to know your fake identities. First player to break character pays the entire group\'s next round with no exceptions.',  xp:130 },
      { id:'b_qh35', title:'The Night Detectives Four',   desc:'All four pick the same target stranger at the start of the night without the stranger knowing. Each player independently gathers as many verified facts as possible through observation and indirect conversation only. No direct personal questions allowed. Combine all four player findings at the end into the most complete profile possible.',  xp:125 },
      { id:'b_qh36', title:'The Storyline Weavers Four',  desc:'All four create one ongoing fictional narrative about the bar that grows every time any of them meets someone new. By the end of the night the story must authentically involve at least 20 real people from the bar who all contributed without knowing they were part of it. Recite the complete story to the bartender before leaving.',  xp:120 },
      { id:'b_qh37', title:'The Arbiters Supreme Four',   desc:'All four collectively establish themselves as the undisputed unofficial court of the bar all night. Get at least 14 different strangers to approach them to settle a dispute, seek advice, or receive a formal verdict. Every ruling must be unanimous across all four players.',                                               xp:130 },
      { id:'b_qh38', title:'Speed Hustlers Four',         desc:'All four make small harmless competitive bets with strangers on things they are genuinely confident they can do. Each player must win at least 5 bets across the night. All winnings go into a collective pool used to pay for the entire final round of the night.',                                                           xp:125 },
      { id:'b_qh39', title:'The Complete Observation Four',desc:'Each player independently observes and documents the 10 most interesting things they witness all night without discussing with the others. At the end compare all four lists. Any observation appearing on all four lists scores quadruple. Highest combined score picks the after-party location.',                            xp:120 },
      { id:'b_qh40', title:'The Ultimate Stakes Four',    desc:'All four agree on one genuinely significant consequence at the very start of the night. Compete simultaneously on four different agreed metrics throughout the entire night. A panel of four neutral strangers determines the winner of each metric. The player who loses the most metrics faces the consequence immediately before anyone leaves.',  xp:130 },
      // Fun & Silly
      { id:'b_qh41', title:'The Feature Film Four',       desc:'Player 1 directs and writes the script live. Player 2 is the lead actor. Player 3 is the cinematographer and sound department. Player 4 is the producer managing logistics, timing, and stranger recruitment. Produce a complete 5-minute film with a full arc featuring at least 5 stranger cameos who all knew and consented to their involvement.',  xp:130 },
      { id:'b_qh42', title:'The Complete Method Four',    desc:'All four commit to a fully developed fictional dynamic that none of them break under any circumstances for the entire night. The dynamic must be complex enough that different strangers interact fundamentally differently with each player based on their specific role within the fiction.',                                   xp:125 },
      { id:'b_qh43', title:'Live Podcast Finale Four',    desc:'Player 1 hosts. Player 2 co-hosts. Player 3 is the roving correspondent reporting from different sections of the bar. Player 4 is the executive producer managing topics, timing, and quality. Record a complete 20-minute podcast episode with at least 6 stranger interviews, two live debates, and a closing segment featuring all four reflecting on the night.',  xp:130 },
      { id:'b_qh44', title:'The Quadruple Roast',         desc:'All four roast each other in a full bracket format in front of a gathered audience of willing strangers. Player 1 roasts Player 2. Player 3 roasts Player 4. Winners face each other in the final round. A panel of 4 strangers scores every roast out of 10. The player with the lowest total score across all rounds pays the entire group\'s final tab.',  xp:125 },
      { id:'b_qh45', title:'The Heist Finale Four',       desc:'All four plan and execute a multi-step completely harmless heist requiring all four players to execute specific simultaneous roles at specific times. The objective must be agreed and detailed before entering the bar and completed within 90 minutes using only charm, timing, distraction, and flawless coordination.',        xp:120 },
      { id:'b_qh46', title:'Four Man Show',               desc:'All four develop and perform a complete 6-minute live show for a willing audience of strangers gathered at the bar. The show must have a clear format, a strong opening, a middle, and a memorable ending. The audience must be involved at least three times. Get a genuine standing ovation or sustained applause from at least 8 strangers.',  xp:130 },
      { id:'b_qh47', title:'The Slow Build Masterpiece Four',desc:'Player 1 plants a callback at the very start of the night with 8 different strangers. Player 2 references it mid-night. Player 3 references it again later in the evening. Player 4 pays off every single callback in one final coordinated moment at the very end of the night in front of as many of those original 8 strangers as possible.',  xp:125 },
      { id:'b_qh48', title:'The Farewell Epic Four',      desc:'All four tell every stranger they meet throughout the entire night that the squad is permanently breaking up after tonight — all four are moving to different cities and this is their absolute final night together. Make every single interaction feel genuinely historic. Get at least 15 strangers to offer a sincere and emotional goodbye to the group before you leave.',  xp:120 },
      { id:'b_qh49', title:'The Living Legend Arc Four',  desc:'Player 1 does something genuinely and memorably remarkable in the first hour. Player 2 builds the legend of that moment throughout the middle of the night. Player 3 creates a physical artifact commemorating it. Player 4 orchestrates a full callback to the moment at the very end of the night in front of the largest possible audience. Every stage of the arc must involve real strangers as authentic witnesses.',  xp:130 },
      { id:'b_qh50', title:'Night Quest Quad Legend',     desc:'All four players complete at least 4 easy, 4 medium, and 3 hard quad missions in a single night, get recognized by staff and at least 6 strangers as an unforgettable group, have three different strangers give genuine on-camera testimonials about the squad, have the bartender personally and enthusiastically say goodbye to all four players by name, and have at least one staff member ask when you\'re all coming back before you walk out the door.',  xp:150 },
    ],
  },
}

// Pick n quad quests for a 4-player squad
export function pickQuadQuestSet(outingId, difficultyId, excludeIds = null) {
  return pickFromRolePool(SQUAD_QUAD_QUESTS, outingId, difficultyId, excludeIds)
}

