export function pickDecaQuestSet(outingId, difficultyId, excludeIds = null) {
  return pickFromRolePool(SQUAD_DECA_QUESTS, outingId, difficultyId, excludeIds)
}

// ─── Venue Quests (Club / Rave / Open Mic / Casino) — all squad sizes 2–10 ──
export { SQUAD_VENUE_QUESTS } from './venueQuests'

// Unified picker for all non-bar venues
export function pickSquadVenueQuests(outingId, difficultyId, playerCount, excludeIds = null) {
  const diff = DIFFICULTIES.find(d => d.id === difficultyId)
  const n = diff?.taskCount || 5
  const fullPool = _VQ[outingId]?.[playerCount]?.[difficultyId] || []
  const pool = excludeIds && excludeIds.size > 0
    ? (fullPool.filter(t => !excludeIds.has(t.id)).length >= n
        ? fullPool.filter(t => !excludeIds.has(t.id))
        : fullPool)   // exhausted → full pool
    : fullPool
  const a = [...pool]
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]]
  }
  return a.slice(0, Math.min(n, a.length))
}
